import re,json,html,pathlib
out={}
for n in ['digitalocean-write','draftdev-write','logrocket-guest']:
  t=pathlib.Path('products/research/paid-editorial/raw/'+n+'.html').read_text(errors='replace')
  t=re.sub(r'(?s)<script.*?</script>|<style.*?</style>',' ',t)
  t=html.unescape(re.sub(r'<[^>]+>',' ',t)); t=re.sub(r'\s+',' ',t)
  hits=[]
  for k in [r'\$\s?\d[\d,]*',r'USD',r'\bpay',r'paid',r'\bAI\b',r'artificial',r'ChatGPT',r'generat',r'LLM',r'eligib',r'countr',r'rights',r'licens',r'apply',r'application',r'pause',r'closed',r'not accepting',r'Write for DOnations',r'honorari',r'per article',r'donat']:
    for m in re.finditer(k,t,re.I):
      s=t[max(0,m.start()-200):m.end()+200]
      if s not in hits: hits.append(s)
      if len(hits)>40: break
  out[n]={'chars':len(t),'snippets':[k for k in hits][:40]}
pathlib.Path('products/research/paid-editorial/extract.json').write_text(json.dumps(out,indent=1))
print(json.dumps({k:v['chars'] for k,v in out.items()}))
